#include <iostream>
#include <queue>
#include <cstring>
#include <vector>
#include <algorithm>
using namespace std;

const int MAXN = 15;
const int INF = 1000000000;

int n, T;
char grid[MAXN][MAXN], target[MAXN][MAXN];
int id[MAXN][MAXN], total;
int distFromZ[MAXN][MAXN];

struct Edge {
    int to, cap;
    Edge(int t, int c) : to(t), cap(c) {}
};

vector<Edge> graph[3005];
vector<int> revIndex[3005];

void addEdge(int u, int v, int cap) {
    graph[u].push_back(Edge(v, cap));
    revIndex[u].push_back(graph[v].size());
    graph[v].push_back(Edge(u, 0));
    revIndex[v].push_back(graph[u].size() - 1);
}

bool bfsLevel(int source, int sink, vector<int>& level) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    q.push(source);
    level[source] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = 0; i < graph[u].size(); ++i) {
            Edge& e = graph[u][i];
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[sink] != -1;
}

int dfs(int u, int sink, int flow, vector<int>& iter, vector<int>& level) {
    if (u == sink) return flow;
    for (int& i = iter[u]; i < graph[u].size(); ++i) {
        Edge& e = graph[u][i];
        if (e.cap > 0 && level[e.to] == level[u] + 1) {
            int pushed = dfs(e.to, sink, min(flow, e.cap), iter, level);
            if (pushed > 0) {
                e.cap -= pushed;
                graph[e.to][revIndex[u][i]].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int dinic(int source, int sink) {
    int flow = 0;
    vector<int> level(3005);
    while (bfsLevel(source, sink, level)) {
        vector<int> iter(3005, 0);
        int pushed;
        while ((pushed = dfs(source, sink, INF, iter, level)) > 0) {
            flow += pushed;
        }
    }
    return flow;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> T;
    for (int i = 0; i < n; ++i) cin >> grid[i];
    for (int i = 0; i < n; ++i) cin >> target[i];

    int sx = -1, sy = -1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Z') {
                sx = i; sy = j;
                grid[i][j] = '0';
            }
            id[i][j] = ++total;
        }
    }

    // BFS from Z position
    queue<pair<int, int>> q;
    memset(distFromZ, 0x3f, sizeof(distFromZ));
    if (sx != -1 && sy != -1) {
        distFromZ[sx][sy] = 0;
        q.push({sx, sy});
    }
    const int dx[] = {0, 0, -1, 1};
    const int dy[] = {1, -1, 0, 0};
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                grid[nx][ny] >= '0' && grid[nx][ny] <= '9' &&
                distFromZ[nx][ny] > distFromZ[x][y] + 1) {
                distFromZ[nx][ny] = distFromZ[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }

    int source = 2 * total + 1;
    int sink = source + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                addEdge(source, id[i][j], grid[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (target[i][j] >= '1' && target[i][j] <= '9') {
                addEdge(id[i][j] + total, sink, target[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] >= '1' && grid[i][j] <= '9') {
                int dist[MAXN][MAXN];
                memset(dist, 0x3f, sizeof(dist));
                queue<pair<int, int>> localQ;
                dist[i][j] = 0;
                localQ.push({i, j});
                while (!localQ.empty()) {
                    auto [x, y] = localQ.front(); localQ.pop();
                    for (int k = 0; k < 4; ++k) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n &&
                            grid[nx][ny] >= '0' && grid[nx][ny] <= '9' &&
                            dist[nx][ny] > dist[x][y] + 1) {
                            dist[nx][ny] = dist[x][y] + 1;
                            localQ.push({nx, ny});
                        }
                    }
                }
                for (int x = 0; x < n; ++x) {
                    for (int y = 0; y < n; ++y) {
                        if (target[x][y] >= '1' && target[x][y] <= '9' &&
                            dist[x][y] <= T && dist[x][y] <= distFromZ[x][y]) {
                            addEdge(id[i][j], id[x][y] + total, INF);
                        }
                    }
                }
            }
        }
    }

    cout << dinic(source, sink) << '\n';
    return 0;
}
